package com.casystem.onboarding.controller;import com.casystem.onboarding.model.AuditLog;import com.casystem.onboarding.repository.AuditLogRepository;import com.casystem.onboarding.service.TokenService;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/audit") @CrossOrigin(origins="*") public class AuditController{private final AuditLogRepository repo;private final TokenService tokens;public AuditController(AuditLogRepository r,TokenService t){repo=r;tokens=t;}@GetMapping public List<AuditLog> mine(@RequestHeader("Authorization")String h){return repo.findByUserIdOrderByCreatedAtDesc(tokens.userId(h));}}